import sys
from collections import defaultdict

def read_input():
    import sys
    data = sys.stdin.read().strip().split('\n')
    A, B = map(int, data[0].split())
    picture = data[1:]
    return A, B, picture

def get_pieces(A, B, picture, X, Y):
    pieces = []
    for i in range(0, A, X):
        for j in range(0, B, Y):
            piece = []
            for x in range(X):
                piece.append(picture[i + x][j:j + Y])
            pieces.append(''.join(piece))
    return pieces

def is_good_puzzle(pieces):
    seen = set()
    for piece in pieces:
        rotations = {piece[i:] + piece[:i] for i in range(len(piece))}
        if any(rot in seen for rot in rotations):
            return False
        seen.add(piece)
    return True

def main():
    A, B, picture = read_input()
    good_puzzles = []
    min_area = float('inf')
    min_piece = (float('inf'), float('inf'))

    for X in range(1, A + 1):
        if A % X != 0:
            continue
        for Y in range(1, B + 1):
            if B % Y != 0:
                continue
            pieces = get_pieces(A, B, picture, X, Y)
            if is_good_puzzle(pieces):
                good_puzzles.append((X, Y))
                area = X * Y
                if area < min_area or (area == min_area and X < min_piece[0]):
                    min_area = area
                    min_piece = (X, Y)

    print(len(good_puzzles))
    print(min_piece[0], min_piece[1])

if __name__ == "__main__":
    main()
